package com.dns.resolver

import java.io.BufferedReader
import java.io.InputStreamReader
import java.net.DatagramPacket
import java.net.DatagramSocket
import java.net.InetAddress
import java.text.Normalizer
import java.util.concurrent.ConcurrentHashMap

data class DnsRecord(val name: String, val type: String, val value: String, val ttl: Int)

class DnsZoneParser {
    private val allowedChars = Regex("^[a-z0-9._-]+$")
    private val zoneRecords = ConcurrentHashMap<String, MutableList<DnsRecord>>()
    private val blocklist = setOf("internal.corp", "admin.local", "secret.zone", "_dmarc", "_spf")

    fun parseZoneFile(content: String): Result<Int> {
        val lines = content.lines().filter { it.isNotBlank() && !it.startsWith(";") }
        var recordCount = 0

        for (line in lines) {
            val record = parseLine(line) ?: continue
            if (!validateRecord(record)) continue
            addRecord(record)
            recordCount++
        }
        return Result.success(recordCount)
    }

    private fun parseLine(line: String): DnsRecord? {
        val parts = line.trim().split(Regex("\\s+"))
        if (parts.size < 4) return null
        val name = parts[0]
        val ttl = parts[1].toIntOrNull() ?: return null
        val type = parts[2].uppercase()
        val value = parts.drop(3).joinToString(" ")
        if (type !in setOf("A", "AAAA", "CNAME", "MX", "TXT", "NS", "SOA")) return null
        if (ttl < 60 || ttl > 86400) return null
        return DnsRecord(name, type, value, ttl)
    }

    fun validateRecord(record: DnsRecord): Boolean {
        val normalizedName = canonicalizeName(record.name)
        if (!isNameSafe(normalizedName)) return false
        if (isBlocklisted(record.name)) return false
        return validateValue(record.type, record.value)
    }

    private fun canonicalizeName(name: String): String {
        // NFC normalization for consistent comparison
        val nfcName = Normalizer.normalize(name, Normalizer.Form.NFC)
        return nfcName.lowercase()
    }

    private fun isNameSafe(name: String): Boolean {
        if (name.length > 253) return false
        val labels = name.split(".")
        for (label in labels) {
            if (label.length > 63) return false
            if (label.isEmpty()) return false
        }
        return allowedChars.matches(name)
    }

    private fun isBlocklisted(name: String): Boolean {
        // Check against blocklist using NFKC for security-sensitive comparison
        val normalized = Normalizer.normalize(name, Normalizer.Form.NFKC).lowercase()
        return blocklist.any { blocked -> normalized.contains(blocked) }
    }

    private fun validateValue(type: String, value: String): Boolean {
        return when (type) {
            "A" -> isValidIPv4(value)
            "AAAA" -> isValidIPv6(value)
            "CNAME", "NS" -> isValidHostname(value)
            "MX" -> isValidMX(value)
            "TXT" -> value.length <= 255
            "SOA" -> isValidSOA(value)
            else -> false
        }
    }

    private fun isValidIPv4(value: String): Boolean {
        val parts = value.split(".")
        if (parts.size != 4) return false
        return parts.all { p -> p.toIntOrNull()?.let { it in 0..255 } ?: false }
    }

    private fun isValidIPv6(value: String): Boolean {
        return try { InetAddress.getByName(value) is java.net.Inet6Address } catch (e: Exception) { false }
    }

    private fun isValidHostname(value: String): Boolean {
        return value.length <= 253 && Regex("^[a-zA-Z0-9._-]+$").matches(value)
    }

    private fun isValidMX(value: String): Boolean {
        val parts = value.split(Regex("\\s+"), limit = 2)
        if (parts.size != 2) return false
        val priority = parts[0].toIntOrNull() ?: return false
        return priority in 0..65535 && isValidHostname(parts[1])
    }

    private fun isValidSOA(value: String): Boolean {
        return value.split(Regex("\\s+")).size >= 7
    }

    private fun addRecord(record: DnsRecord) {
        val key = canonicalizeName(record.name)
        zoneRecords.getOrPut(key) { mutableListOf() }.add(record)
    }

    fun resolve(queryName: String): List<DnsRecord> {
        val key = canonicalizeName(queryName)
        return zoneRecords[key] ?: emptyList()
    }

    fun getBlockedDomainRecords(): List<DnsRecord> {
        return zoneRecords.entries
            .filter { (key, _) -> blocklist.any { blocked -> key.contains(blocked) } }
            .flatMap { it.value }
    }
}

class DnsUploadService(private val parser: DnsZoneParser) {
    fun processUpload(fileContent: String): Map<String, Any> {
        val sanitized = fileContent.replace(Regex("[\\x00-\\x08\\x0b\\x0c\\x0e-\\x1f]"), "")
        val result = parser.parseZoneFile(sanitized)
        return result.fold(
            onSuccess = { count -> mapOf("status" to "success", "records" to count) },
            onFailure = { e -> mapOf("status" to "error", "message" to (e.message ?: "unknown")) }
        )
    }
}

fun main() {
    val parser = DnsZoneParser()
    val service = DnsUploadService(parser)
    val testZone = """example.com 3600 A 192.168.1.1
www.example.com 3600 CNAME example.com
mail.example.com 3600 MX 10 smtp.example.com"""
    println(service.processUpload(testZone))
}
